import {
    closest,
    createElement,
    getEl,
    toggleClass,
    getDecade, 
    getParsedDate,
    removeClass,
    template
} from './common/utils';
import consts, { DatepickerView } from './common/consts';
import  { DatepickerOptions } from './Default';
import './DatepickerNav.scss';

interface DatepickerNavArgs {
   dp: {
        currentView: DatepickerView;
        viewDate: Date;
        formatDate: (date: Date, format: string) => string;
        [key: string]: any;
    };
    opts: DatepickerOptions;
}

export default class DatepickerNav {
    dp: any;
    opts: DatepickerOptions;
    $el!: HTMLElement;
    $title!: HTMLElement;
    $prev!: HTMLElement;
    $next!: HTMLElement;

    constructor({ dp, opts }: DatepickerNavArgs) {
        this.dp = dp;
        this.opts = opts;

        this.init();
    }

    init(): void {
        this._createElement();
        this._buildBaseHtml();
        this._defineDOM();

        this.render();

        this.handleNavStatus();
        this._bindEvents();
        this._bindDatepickerEvents();
    }

    _defineDOM(): void {
        this.$title = getEl('.datepicker-nav--title', this.$el) as HTMLElement;
        this.$prev = getEl('[data-action="prev"]', this.$el) as HTMLElement;
        this.$next = getEl('[data-action="next"]', this.$el) as HTMLElement;
    }

    _bindEvents(): void {
        this.$el.addEventListener('click', this.onClickNav);
        this.$title.addEventListener('click', this.onClickNavTitle);
    }

    _bindDatepickerEvents(): void {
        this.dp.on(consts.eventChangeViewDate, this.onChangeViewDate);
        this.dp.on(consts.eventChangeCurrentView, this.onChangeCurrentView);

        if (this.isNavIsFunction) {
            // Wait till time is added to date
            this.dp.on(consts.eventChangeSelectedDate, this.renderDelay);

            if (this.dp.opts.timepicker) {
                this.dp.on(consts.eventChangeTime, this.render);
            }
        }
    }

    destroy(): void {
        this.dp.off(consts.eventChangeViewDate, this.onChangeViewDate);
        this.dp.off(consts.eventChangeCurrentView, this.onChangeCurrentView);
        
        if (this.isNavIsFunction) {
            this.dp.off(consts.eventChangeSelectedDate, this.renderDelay);
            if (this.dp.opts.timepicker) {
                this.dp.off(consts.eventChangeTime, this.render);
            }
        }
    }

    _createElement(): void {
        this.$el = createElement({
            tagName: 'nav',
            className: 'datepicker-nav'
        });
    }

    _getTitle(viewDate: Date = this.dp.viewDate): string {
        const navTitles = this.opts.navTitles || {};
        const viewType = this.dp.currentView as keyof typeof navTitles;
        const templateString = navTitles[viewType] || '';
        if (typeof templateString === 'function') {
            return templateString(this.dp);
        }
        const replacer = (part: string) => {
            return this.dp.formatDate(viewDate, part);
        };

        return template(templateString, replacer);
    }

    handleNavStatus(): void {
        const { disableNavWhenOutOfRange } = this.opts;
        const { minDate, maxDate } = this.dp;
        if (!(minDate || maxDate) || !disableNavWhenOutOfRange) return;

        const { year, month } = this.dp.parsedViewDate;
        const minDateParsed = minDate ? getParsedDate(minDate) : false;
        const maxDateParsed = maxDate ? getParsedDate(maxDate) : false;

        switch (this.dp.currentView) {
            case consts.days:
                if (minDateParsed && minDateParsed.month >= month && minDateParsed.year >= year) {
                    this._disableNav('prev');
                }
                if (maxDateParsed && maxDateParsed.month <= month && maxDateParsed.year <= year) {
                    this._disableNav('next');
                }
                break;
            case consts.months:
                if (minDateParsed && minDateParsed.year >= year) {
                    this._disableNav('prev');
                }
                if (maxDateParsed && maxDateParsed.year <= year) {
                    this._disableNav('next');
                }
                break;
            case consts.years: {
                const decade = getDecade(this.dp.viewDate);
                if (minDateParsed && minDateParsed.year >= decade[0]) {
                    this._disableNav('prev');
                }
                if (maxDateParsed && maxDateParsed.year <= decade[1]) {
                    this._disableNav('next');
                }
                break;
            }
        }
    }

    _disableNav(actionName: 'prev' | 'next'): void {
        const el = getEl('[data-action="' + actionName + '"]', this.$el);
        el?.classList.add('-disabled-');
    }

    _resetNavStatus(): void {
        const actions = this.$el.querySelectorAll('.datepicker-nav--action');
        removeClass(actions, '-disabled-');
    }

    onClickNav = (e: MouseEvent): void => {
        const target = e.target as HTMLElement;
        const $item = closest(target, '.datepicker-nav--action');
        if (!$item) return;

        const actionName = $item.dataset.action as 'prev' | 'next';

        // actionName will be 'prev' or 'next', which are methods on Datepicker
        if (actionName && typeof this.dp[actionName] === 'function') {
            this.dp[actionName]();
        }
    }

    onChangeViewDate = (): void => {
        this.render();
        this._resetNavStatus();
        this.handleNavStatus();
    }

    onChangeCurrentView = (): void => {
        this.render();
        this._resetNavStatus();
        this.handleNavStatus();
    }

    onClickNavTitle = (): void => {
        if (this.dp.isFinalView) return;
        this.dp.up();
    }

    _buildBaseHtml(): void {
        const { prevHtml, nextHtml } = this.opts;

        this.$el.innerHTML = '' +
            `<div class="datepicker-nav--action" data-action="prev">${prevHtml}</div>` +
            '<div class="datepicker-nav--title"></div>' +
            `<div class="datepicker-nav--action" data-action="next">${nextHtml}</div>`;
    }

    get isNavIsFunction(): boolean {
        const { navTitles } = this.opts;
        if (!navTitles) return false;

        return Object.keys(navTitles).some((view) => {
            return typeof (navTitles as any)[view] === 'function';
        });
    }

    update = (): void => {
        const { prevHtml, nextHtml } = this.opts;

        this.$prev.innerHTML = prevHtml!;
        this.$next.innerHTML = nextHtml!;

        this._resetNavStatus();
        this.render();
        this.handleNavStatus();
    }

    renderDelay = (): void => {
        setTimeout(this.render);
    }

    render = (): void => {
        this.$title.innerHTML = this._getTitle();
        toggleClass(this.$title, {
            '-disabled-': this.dp.isFinalView
        });
    }
}